1	/**
2	 * branch-placement.ts — which branch a run's work goes on, and what its pull
3	 * request aims at.
4	 *
5	 * The naming rule itself is pure and lives in `domain/work/issue-branch.ts`. What is
6	 * here is everything that has to ask git or GitHub to apply it: whether a branch
7	 * already exists, whether this issue has a parent, where a new branch should be
8	 * cut from, and whether a parent's branch is there to stack on.
9	 *
10	 * `repo` is passed rather than read from the environment, so the decision is
11	 * never quietly about a different repository than the caller meant.
12	 */
13	import { gh, gitRun } from "./gh.ts";
14	import { parentIssueOf, type ParentIssue } from "./parent-issue.ts";
15	import { isIssueRun, nodeNumber } from "../runner/run-node.ts";
16	import { nextOrdinal } from "../../domain/work/issue-branch.ts";
17	import { collectIssueBranches } from "./issue-branches.ts";
