34	/**
35	 * What to say when this run has no branch at all.
36	 *
37	 * The state, not the symptom. This used to be "Cannot determine branch name; set
38	 * BRANCH env", and before that the third route below handed git's own description
39	 * of a detached HEAD -- `(HEAD detached at pull/802/head)` -- to `git push -u
40	 * origin <that>`, which answered `fatal: invalid refspec`. An agent reading a raw
41	 * git failure concludes the tool is broken; what it needs to know is that this
42	 * checkout has no branch to push, so there is nothing for these tools to publish.
43	 */
44	const NO_BRANCH_MESSAGE =
45	  "This run is on a detached checkout with no local branch, so there is no branch to push: " +
46	  "commit_and_push and create_pr cannot publish this run's work. Report the work on the issue instead.";
47	
48	/**
49	 * Whether `name` is a branch that exists locally -- `refs/heads/<name>` -- rather
50	 * than a name git merely printed.
51	 *
52	 * Asked rather than assumed, because every route below can hand back a string that
53	 * looks like a branch and is not one: `git branch --points-at HEAD` prints its own
54	 * pseudo-entry for a detached HEAD, and `BRANCH` is set by the runner from
55	 * whatever `git rev-parse --abbrev-ref HEAD` said. `git show-ref --verify` is the
56	 * check git itself uses for "is this a ref", so a name that is not one -- including
57	 * the pseudo-entry, whose parentheses are not valid in a refname -- fails here
58	 * rather than at the push.
59	 */
60	function isLocalBranch(name: string): boolean {
61	  if (!name || name === "HEAD" || name.startsWith("(")) return false;
62	  return gitRun("show-ref", "--verify", "--quiet", `refs/heads/${name}`).code === 0;
63	}
64	
65	/**
66	 * The branch this run is checked out on, however it can be determined.
67	 *
68	 * Every route answers only with a name that resolves as `refs/heads/<name>`, and
69	 * nothing resolves to the literal `HEAD`, an empty string, or git's description of
70	 * a detached HEAD. A route that cannot answer falls through to the next; when none
71	 * can, the run has no branch and says so (see `NO_BRANCH_MESSAGE`).
72	 */
73	export function resolveBranch(): string {
74	  const fromEnv = (process.env.BRANCH ?? "").trim();
75	  if (isLocalBranch(fromEnv)) return fromEnv;
76	  {
77	    const { code, stdout } = gitRun("rev-parse", "--abbrev-ref", "HEAD");
78	    const name = code === 0 ? stdout.trim() : "";
79	    if (isLocalBranch(name)) return name;
80	  }
81	  {
82	    // The case this route allows: a detached HEAD at a commit that a LOCAL branch
83	    // points at, so there is a name the work belongs on and a branch to push.
84	    //
85	    // The case it rejects, and the one a `pr` run is in: a detached HEAD at a commit
86	    // that only a remote-tracking or `refs/pull/<n>/head` ref points at. That commit
87	    // is a tip of something, but nothing local names it, so there is no branch to
88	    // push and the honest answer is the refusal below rather than a string git will
89	    // reject as a refspec.
90	    //
91	    // `git branch --points-at HEAD` lists the allowed branch -- but its first line is
92	    // git's own pseudo-entry for the detached HEAD, `(HEAD detached at
93	    // pull/802/head)`, which `--format` does not suppress and which is a description
94	    // rather than a ref. Every line is therefore checked, not just the first: a name
95	    // beginning with `(` and a name that does not resolve as `refs/heads/<name>` are
96	    // both rejected.
97	    const { code, stdout } = gitRun("branch", "--format=%(refname:short)", "--points-at=HEAD");
98	    if (code === 0) {
99	      for (const line of stdout.split("\n")) {
100	        const name = line.trim();
101	        if (isLocalBranch(name)) return name;
102	      }
103	    }
104	  }
105	  throw new Error(NO_BRANCH_MESSAGE);
106	}
