109	/**
110	 * The branch a sub-issue's work should be cut from, or "" for the base branch.
111	 *
112	 * Sub-issues of one parent are split from a single piece of work and usually
113	 * depend on each other — an interface one defines is what the next one consumes.
114	 * Cutting each from the base hides those from one another until every part has
115	 * landed separately, which is where integration surprises come from.
116	 *
117	 * So they stack: each is cut from the parent's branch and merges back into it,
118	 * and the parent's branch reaches the base as one reviewed change. The parent's
119	 * branch is created here, empty, if the first child gets there first — an
120	 * atomaton plans and dispatches without committing, so its branch would
121	 * otherwise not exist yet.
122	 *
123	 * Best-effort throughout. Every failure returns "" and the work is cut from the
124	 * base, which is the behaviour before stacking existed: a slower integration is
125	 * not worth failing a commit over.
126	 */
127	export function stackedBaseFor(repo: string, issue: number): string {
128	  // An unreadable parent falls in with every other failure here: cut from the
