130	  const found = parentIssueOf(repo, issue);
131	  if (!found.known || !found.parent) return "";
132	
133	  const parentBranch = branchOfIssue(found.parent);
134	  const existing = gitRun("ls-remote", "--heads", "origin", `refs/heads/${parentBranch}`);
135	  if (existing.code === 0 && existing.stdout.trim()) {
