163	/**
164	 * The branch this commit belongs on, creating one if the run has none yet.
165	 *
166	 * A run starts on the base branch unless it had work to resume, because most
167	 * runs never commit and creating a branch for those left one behind every time.
168	 * The first commit is what turns a run into work, so that is where the branch
169	 * appears.
170	 *
171	 * When every earlier branch for this issue has merged, the name counts up:
172	 * reusing a merged branch would build on history the base already contains.
173	 */
174	export function branchForCommit(repo: string): string {
175	  const current = gitRun("rev-parse", "--abbrev-ref", "HEAD");
176	  const onBranch = current.code === 0 ? current.stdout.trim() : "";
177	  if (isIssueBranch(onBranch)) return onBranch;
178	
179	  // Only an issue run may name a branch. On a pull request run `NUMBER` holds the
180	  // PR's number and the checkout is already the branch under review, so naming one
181	  // from it would move the work off the pull request.
182	  const issue = runIssueNumber();
183	  if (issue === undefined) return resolveBranch();
184	
185	  const from = stackedBaseFor(repo, issue);
186	  // Refused rather than guessed. An unread list makes `nextOrdinal` answer with the
187	  // FIRST name, which is the one most likely to exist already -- and the run then fails
188	  // at the push, reporting a non-fast-forward instead of the read that caused it.
189	  const listed = collectIssueBranches(repo, issue);
190	  if (!listed.known) {
191	    throw new Error(
192	      `${listed.why}, so a new branch for #${issue} cannot be named without risking one that already exists.`,
193	    );
194	  }
195	  const name = branchNameFor(issue, nextOrdinal(listed.branches));
196	  const created = from
197	    ? gitRun("checkout", "-b", name, `origin/${from}`)
198	    : gitRun("checkout", "-b", name);
199	  if (created.code) throw new Error(`Could not create branch '${name}': ${created.stderr || created.stdout}`);
200	  log(`commitAndPush: created branch ${name}${from ? ` from ${from}` : ""}`);
201	  return name;
202	}
203	
204	/**
205	 * The parent's branch, when this run is a sub-issue's and that branch exists.
206	 *
207	 * Returns undefined for a root issue, and for a sub-issue whose parent branch
208	 * was never created — a run that reports rather than commits reaches no
209	 * `commit_and_push`, so nothing made one, and there is nothing to stack on.
210	 *
211	 * The parent's own run is a root run by this test: its issue carries no parent
212	 * tag, so its pull request — the integration one, carrying every child's work —
213	 * targets the base branch like any other.
214	 *
215	 * Throws when the issue could not be read, rather than answering undefined.
216	 * Unlike `stackedBaseFor`, this caller cannot absorb the uncertainty: its answer
217	 * decides where a pull request merges to, and guessing the base branch for a
218	 * sub-issue lands one child's half of a feature on the release branch and
219	 * deploys it. A tool error the agent can retry is the cheaper wrong answer.
220	 */
221	export function stackedPrBase(repo: string): string | undefined {
222	  const issue = runIssueNumber();
223	  if (issue === undefined) return undefined;
224	
225	  const found = parentIssueOf(repo, issue);
226	  if (!found.known) {
227	    throw new Error(
228	      `Cannot tell whether issue #${issue} is a sub-issue, so the base branch for its pull request is unknown: ` +
229	        `${found.why}. Retry the call.`,
230	    );
231	  }
232	  if (!found.parent) return undefined;
233	
234	  const parentBranch = branchOfIssue(found.parent);
235	  const { code, stdout } = gitRun("ls-remote", "--heads", "origin", `refs/heads/${parentBranch}`);
236	  return code === 0 && stdout.trim() ? parentBranch : undefined;
237	}
238	
239	/**
240	 * The issue this run is working on, or undefined when it is not an issue run.
241	 *
242	 * Both callers above need the same two conditions — the run is an issue run,
243	 * and the number is a real one — and both are wrong in the same way if either
244	 * is dropped: a pull request run's `NUMBER` is the pull request's number,
245	 * and treating it as an issue moves work off the branch under review.
246	 */
247	function runIssueNumber(): number | undefined {
248	  if (!isIssueRun()) return undefined;
249	  return nodeNumber();
250	}

