62	/**
63	 * Run a READ through `gh`, treating an upstream failure as no answer rather than as
64	 * an answer of "no".
65	 *
66	 * GitHub returned `HTTP 504` for one `gh api repos/.../pulls/427` call and the run
67	 * died on it: the reviewer never started, and the pull request carried a red check
68	 * for a defect in neither the code nor the machinery. There is nothing to learn from
69	 * a 504 and nothing for an agent to do about it.
70	 *
71	 * Reads only, which is the whole reason this is a separate function rather than a
72	 * change to `gh` itself. A mutation that returns 502 may well have been applied, and
73	 * the invariants here are the kind a second attempt breaks -- one comment per run,
74	 * one dispatch per handoff. So the retry has to be asked for, by a caller that knows
75	 * its call changes nothing.
76	 *
77	 * Three attempts, widening, because the point is to outlast a blip rather than to
78	 * sit out an outage: a run holds a runner while it sleeps.
79	 */
80	export function ghRead(...args: string[]): RunResult {
81	  let result = gh(...args);
82	  for (const delay of [2_000, 6_000]) {
83	    if (result.code === 0 || !looksTransient(result)) return result;
84	    console.error(
85	      `::warning::gh ${args.slice(0, 2).join(" ")} failed transiently, retrying: ${result.stderr || result.stdout}`,
86	    );
87	    Bun.sleepSync(delay);
88	    result = gh(...args);
89	  }
90	  return result;
91	}
92	
93	/**
94	 * Whether a failure came from the far end rather than from the request.
95	 *
96	 * A 404 is an answer; a 504 is the absence of one. 429 belongs here as well: it is a
97	 * request to wait, and waiting is what a retry does.
98	 */
99	export function looksTransient(result: RunResult): boolean {
100	  const text = `${result.stderr} ${result.stdout}`;
101	  // Character classes rather than shorthand: this line has lost a backslash to
102	  // tooling twice, and `5dd` compiles just as happily as the version that works.
103	  if (/HTTP (429|5[0-9][0-9])(?![0-9])/.test(text)) return true;
104	  return /(timeout|timed out|connection reset|unexpected EOF|TLS handshake|temporary failure)/i.test(text);
105	}
106	
107	/**
108	 * Run `gh` and keep its stdout as bytes.
109	 *
110	 * `gh` above decodes stdout as UTF-8 and trims it, which is right for JSON and
111	 * ruinous for anything else: a PNG through that comes out as replacement
112	 * characters with its ends shaved off. Anything binary — an attached image, a
113	 * downloaded asset — has to come through here instead.
